using System.Net;
using System.Net.NetworkInformation;
using System.Net.Sockets;
using System.Net.Http.Json;
using System.Text.Json;
using Lmu.Manager;
using Lmu.Web;

static class B251Tests
{
 public static async Task Run(Action<bool,string> check)
 {
  var profile=new NetworkProfile(Guid.NewGuid(),true,0,"11111111-1111-1111-1111-111111111111");
  string Reason(bool physical=true,bool virt=false,NetworkInterfaceType type=NetworkInterfaceType.Ethernet,string name="SYNTHETIC Ethernet",NetworkProfile? p=null,bool vpn=false)=>WindowsPrivateNetworks.CandidateReason(physical,virt,type,name,p??profile,IPAddress.Parse("192.168.20.4"),24,vpn);
  check(Reason()=="","connected physical public profile is a candidate, not automatic trust");check(Reason(p:profile with{Category=1})=="","private Windows profile still needs application trust");check(Reason(virt:true).Length>0&&Reason(physical:false).Length>0,"virtual or unproved hardware excluded");check(Reason(type:NetworkInterfaceType.Tunnel).Length>0&&Reason(type:NetworkInterfaceType.Ppp).Length>0,"tunnel and PPP interfaces excluded");check(Reason(name:"SYNTHETIC Wi-Fi Direct Virtual Hotspot").Length>0,"hosted hotspot adapter excluded");check(Reason(vpn:true).Length>0,"active detected VPN blocks candidate approval");check(Reason(p:profile with{NetworkId=""}).Length>0&&Reason(p:profile with{Category=2}).Length>0,"unknown identity and domain profile fail closed");
  var a=new PrivateInterface("SYNTHETIC-A",IPAddress.Parse("127.0.0.2"),8,"SYNTHETIC Ethernet A",profile.NetworkId,0,"127.0.0.1","SYNTHETIC-MAC-A","Ethernet",true,EnvironmentKey:"SYNTHETIC topology");var b=a with{Id="SYNTHETIC-B",Address=IPAddress.Parse("127.0.0.3"),Name="SYNTHETIC Ethernet B"};
  var baseSettings=new ManagerSettings(false,false,5087,true);NetworkApproval Approval(PrivateInterface n,int port=5087)=>new(n.Fingerprint,port,true,true,true);
  check(NetworkAuthorization.Select(baseSettings,[a,b]) is null,"public profile without explicit approval remains blocked");check(NetworkAuthorization.Select(baseSettings,[a with{Category=1}]) is null,"single private candidate is never implicitly selected");
  var approved=baseSettings with{Network=Approval(a)};check(NetworkAuthorization.Select(approved,[a,b])==a,"approval selects exactly one named current address");check(NetworkAuthorization.Select(approved,[a,a]) is null,"duplicate matching identities cannot be selected");
  foreach(var consent in new[]{Approval(a) with{Trusted=false},Approval(a) with{HttpRiskAccepted=false},Approval(a) with{FirewallUnderstood=false},Approval(a) with{Port=5088}})check(NetworkAuthorization.Select(approved with{Network=consent},[a]) is null,"every trust/HTTP/firewall/port condition is required");
  foreach(var changed in new[]{a with{Address=IPAddress.Parse("127.0.0.4")},a with{PrefixLength=24},a with{Id="NEW"},a with{NetworkId=Guid.NewGuid().ToString()},a with{Gateway="127.0.0.8"},a with{Hardware="NEW MAC"},a with{Category=1},a with{EnvironmentKey="VPN activated"},a with{Eligible=false},a with{Name="Renamed alias"}})check(NetworkAuthorization.Select(approved,[changed]) is null,"changed adapter/address/prefix/profile/gateway/hardware/topology invalidates trust");
  var exe=Path.GetFullPath(Path.Combine("artifacts","SYNTHETIC app","LMU Setup Manager.exe"));bool denied=false;try{NetworkAuthorization.FirewallPlan(new(a.Fingerprint,5087,false),[a],exe);}catch(ArgumentException){denied=true;}check(denied,"firewall help requires explicit consent");
  var plan=JsonSerializer.SerializeToElement(NetworkAuthorization.FirewallPlan(new(a.Fingerprint,5087,true),[a,b],exe));string command=plan.GetProperty("Command").GetString()!;check(command.Contains("-Profile Public")&&command.Contains("-InterfaceAlias 'SYNTHETIC Ethernet A'")&&command.Contains("-LocalAddress '127.0.0.2'")&&command.Contains("-RemoteAddress '127.0.0.0/8'")&&command.Contains("-LocalPort 5087")&&command.Contains("-Program '")&&command.Contains("-EdgeTraversalPolicy Block"),"public-profile firewall proposal jointly scopes executable, adapter, local address, source net and port");
  denied=false;try{NetworkAuthorization.FirewallPlan(new(a.Fingerprint,5087,true),[a with{Address=IPAddress.Parse("127.0.0.4")}],exe);}catch(ArgumentException){denied=true;}check(denied,"stale selection cannot produce firewall guidance");var wildcard=a with{Name="Ethernet*"};denied=false;try{NetworkAuthorization.FirewallPlan(new(wildcard.Fingerprint,5087,true),[wildcard],exe);}catch(ArgumentException){denied=true;}check(denied,"wildcard interface alias cannot broaden firewall rule");
  var root=Path.GetFullPath(Path.Combine("artifacts","b251-tests-"+Guid.NewGuid().ToString("N")));Directory.CreateDirectory(root);var store=new SettingsStore(Path.Combine(root,"config"));var socket=new TcpListener(IPAddress.Loopback,0);socket.Start();int port=((IPEndPoint)socket.LocalEndpoint).Port;socket.Stop();store.Save(new(false,false,port));var networks=new Networks([a,b]);var database=Path.Combine(root,"library.sqlite");ManagerController? manager=new(store,database,networks,new AutoStart());
  async Task Apply(ManagerSettings desired){manager!.RequestSettings(desired);var until=DateTimeOffset.UtcNow.AddSeconds(15);while(manager.View().Changing&&DateTimeOffset.UtcNow<until)await Task.Delay(40);if(manager.View().Changing)throw new Exception("Settings timeout");}
  HttpClient Client(string? token=null){var c=new HttpClient(new HttpClientHandler{UseProxy=false,UseCookies=false}){BaseAddress=new("http://127.0.0.1:"+port),Timeout=TimeSpan.FromSeconds(5)};if(token is not null)c.DefaultRequestHeaders.Authorization=new("Bearer",token);return c;}
  try{
   await manager.StartAsync();await Apply(manager.View().Settings with{LanEnabled=true,Network=null});check(!manager.View().LanActive,"HTTP settings cannot enable unapproved public network");
   using(var anonymous=Client())check((await anonymous.GetAsync("/api/setups")).StatusCode==HttpStatusCode.Unauthorized,"unapproved device receives no library reads");
   var desired=manager.View().Settings with{LanEnabled=true,Network=Approval(a,port)};using(var owner=Client(new Uri(manager.LocalUrl()).Fragment.Split("access=")[1].Split('&')[0])){var session=await owner.GetFromJsonAsync<JsonElement>("/api/session");owner.DefaultRequestHeaders.Add("X-LMU-CSRF",session.GetProperty("csrf").GetString());var response=await owner.PostAsJsonAsync("/api/manager/settings",desired);check(response.StatusCode==HttpStatusCode.Accepted,"owner explicitly approves public selection through protected endpoint without request/shutdown deadlock");}
   var deadline=DateTimeOffset.UtcNow.AddSeconds(15);while(manager.View().Changing&&DateTimeOffset.UtcNow<deadline)await Task.Delay(40);
   check(manager.View().LanActive&&manager.View().Addresses.Length==1&&manager.View().Addresses[0].Contains("127.0.0.2"),"controlled public-profile activation binds only selected loopback test address");var unselected=new TcpListener(IPAddress.Parse("127.0.0.3"),port);unselected.Start();unselected.Stop();check(true,"unselected candidate address is not listening");check(manager.View().NetworkSetup!.LastRemoteContact is null,"active binding never claims device reachability or firewall success without contact");
   var invitation=JsonSerializer.SerializeToElement(manager.Invite("SYNTHETIC device"));string invite=invitation.GetProperty("Urls")[0].GetString()!.Split("access=")[1];string token=manager.RedeemInvitation(invite)!;using(var device=Client(token)){check((await device.GetAsync("/api/setups")).IsSuccessStatusCode,"existing DPAPI device authorization works on explicitly approved public network");check((await device.GetAsync("/api/manager")).StatusCode==HttpStatusCode.Forbidden,"network device still cannot read manager settings");}
   var deviceId=manager.View().Devices.Single().Id;manager.Revoke(deviceId);check(!manager.AuthenticateDevice(token),"individual device revocation unchanged");
   var pending=JsonSerializer.SerializeToElement(manager.Invite("SYNTHETIC before switch")).GetProperty("Urls")[0].GetString()!.Split("access=")[1];networks.Current=[a with{Gateway="127.0.0.9"},b];check(!manager.View().LanActive&&manager.RedeemInvitation(pending) is null,"changed gateway immediately blocks grants before timer cleanup");await manager.CheckNetworkAsync();check(manager.View().Running&&store.Load().LanEnabled&&store.Load().Network==Approval(a,port)&&!manager.View().LanActive,"network change closes access while preserving exact saved approval and intent");
   networks.Current=[a,b];await Apply(manager.View().Settings with{LanEnabled=true,Network=Approval(b,port)});check(manager.View().Addresses.Single().Contains("127.0.0.3"),"explicit second adapter choice never defaults to first");
   await manager.DisposeAsync();manager=new(store,database,networks,new AutoStart());await manager.StartAsync();check(manager.View().LanActive&&manager.View().Addresses.Single().Contains("127.0.0.3"),"restart revalidates exact saved selection, including public profile");networks.Current=[a,b with{EnvironmentKey="new VPN topology",Eligible=false,Reason="VPN"}];check(!manager.View().LanActive,"VPN/topology change immediately removes reported active access");await manager.CheckNetworkAsync();check(!manager.View().LanActive&&manager.View().Running,"VPN change safely stops LAN while loopback survives");
   networks.Current=[a,b];await Apply(manager.View().Settings with{LanEnabled=true,Network=Approval(a,port)});await Apply(manager.View().Settings with{LanEnabled=false});check(!manager.View().LanActive&&manager.View().Devices.Length==0,"explicit disable leaves local server running and previously revoked devices absent");
   store.Save(new(false,false,port,true));await manager.DisposeAsync();manager=new(store,database,networks,new AutoStart());await manager.StartAsync();check(!manager.View().LanActive&&store.Load().LanEnabled&&store.Load().Network is null,"legacy LAN request cannot silently acquire network permission");
  }finally{if(manager is not null)await manager.DisposeAsync();}
 }
 private sealed class Networks(PrivateInterface[] current):IPrivateNetworks{public PrivateInterface[] Current=current;public PrivateInterface[] Read()=>Current;}
 private sealed class AutoStart:IAutoStart{public bool Enabled{get;private set;}public void Set(bool enabled)=>Enabled=enabled;}
}
